-- UNEXECUTED READ-ONLY V2 POSTFLIGHT.
WITH t AS (SELECT 'public.legal_policy_acceptances'::regclass oid), f AS (SELECT p.* FROM pg_proc p WHERE p.oid=to_regprocedure('public.set_legal_policy_acceptance_updated_at()')),
facts AS (SELECT (SELECT count(*) FROM pg_attribute WHERE attrelid=(SELECT oid FROM t) AND attnum>0 AND NOT attisdropped)=14 columns_exact,(SELECT count(*) FROM pg_constraint WHERE conrelid=(SELECT oid FROM t))=12 constraints_exact,(SELECT count(*) FROM pg_index WHERE indrelid=(SELECT oid FROM t))=3 indexes_exact,(SELECT relrowsecurity AND NOT relforcerowsecurity FROM pg_class WHERE oid=(SELECT oid FROM t)) rls_exact,(SELECT count(*) FROM pg_trigger WHERE tgrelid=(SELECT oid FROM t) AND tgname='trg_legal_policy_acceptances_set_updated_at' AND tgfoid=to_regprocedure('public.set_legal_policy_acceptance_updated_at()'))=1 trigger_exact,(SELECT pg_get_userbyid(proowner)='postgres' AND NOT prosecdef AND provolatile='v' AND proparallel='u' AND proconfig=ARRAY['search_path=pg_catalog, public'] FROM f) helper_exact,NOT EXISTS(SELECT 1 FROM pg_proc x CROSS JOIN LATERAL aclexplode(coalesce(x.proacl,acldefault('f',x.proowner))) a WHERE x.oid=(SELECT oid FROM f) AND a.privilege_type='EXECUTE' AND a.grantee IN(0,(SELECT oid FROM pg_roles WHERE rolname='anon'),(SELECT oid FROM pg_roles WHERE rolname='authenticated'),(SELECT oid FROM pg_roles WHERE rolname='service_role'))) helper_acl_exact,NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260712') ledger_unchanged)
SELECT jsonb_build_object('packet_version','legal-consent-forward-only-postflight-v2','classification',CASE WHEN columns_exact AND constraints_exact AND indexes_exact AND rls_exact AND trigger_exact AND helper_exact AND helper_acl_exact AND ledger_unchanged THEN 'LEGAL_CONSENT_CATALOG_V2_EXACT' ELSE 'LEGAL_CONSENT_CATALOG_V2_INCOMPLETE' END,'expected_object_count',53,'facts',to_jsonb(facts)) packet FROM facts;
